const STRIPE_PK =
  "pk_live_51TjE88RnOGoSq5eh6dPxFIqy5AEDd2vAWrUqCnYUvAERSzCCf15j70Pw5UQnEpmFwitn2N7C1c4UxrXTxqIUdFRD008VRDhwY1";

// Load Stripe.js dynamically
const loadStripe = () =>
  new Promise<any>((resolve, reject) => {
    if ((window as any).Stripe) {
      resolve((window as any).Stripe(STRIPE_PK));
      return;
    }
    const existing = document.querySelector(
      'script[src="https://js.stripe.com/v3/"]'
    );
    if (existing) {
      existing.addEventListener("load", () =>
        resolve((window as any).Stripe(STRIPE_PK))
      );
      return;
    }
    const script = document.createElement("script");
    script.src = "https://js.stripe.com/v3/";
    script.async = true;
    script.onload = () => resolve((window as any).Stripe(STRIPE_PK));
    script.onerror = () => reject(new Error("Stripe failed to load"));
    document.head.appendChild(script);
  });

