// ── NavBar ─────────────────────────────────────────────────────────────────────
function NavBar({ page, setPage }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(
    typeof window !== "undefined" ? window.innerWidth <= 640 : false
  );
  const links = ["Home", "Book", "Shop", "About", "Contact"];

  useEffect(() => {
    function handleResize() {
      setIsMobile(window.innerWidth <= 640);
    }
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  function navTo(l) {
    setPage(l);
    setMenuOpen(false);
  }

  return (
    <nav style={{
      position: "sticky", top: 0, zIndex: 100,
      background: "rgba(15,26,10,0.97)",
      backdropFilter: "blur(12px)",
      borderBottom: `2px solid ${COLORS.lime}`,
    }}>
      {/* Top bar */}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "0 1.2rem", height: 58,
      }}>
        {/* Brand */}
        <div onClick={() => navTo("Home")} style={{ cursor: "pointer", display: "flex", alignItems: "center" }}>
          <div style={{ display: "flex", flexDirection: "column", lineHeight: 1 }}>
            <span style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: "clamp(13px, 3.5vw, 17px)", fontWeight: 700,
              color: COLORS.lime, letterSpacing: "0.12em",
            }}>
              Dinkwith<span style={{ color: COLORS.white }}>EQ</span>
            </span>
            <span style={{
              fontFamily: "'DM Sans', sans-serif",
              fontSize: "clamp(8px, 2vw, 10px)", color: COLORS.gray,
              letterSpacing: "0.2em", textTransform: "uppercase", marginTop: 1,
            }}>
              Pickleball Coaching
            </span>
          </div>
        </div>

        {isMobile ? (
          /* Mobile: hamburger */
          <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
            <button
              onClick={() => setMenuOpen((o) => !o)}
              aria-label="Toggle menu"
              style={{
                background: "none", border: "none", cursor: "pointer",
                padding: "4px", display: "flex", flexDirection: "column", gap: 5,
              }}
            >
              <span style={{ display: "block", width: 24, height: 2, background: menuOpen ? COLORS.lime : COLORS.gray, transition: "all .2s", transform: menuOpen ? "rotate(45deg) translate(5px, 5px)" : "none" }} />
              <span style={{ display: "block", width: 24, height: 2, background: menuOpen ? COLORS.lime : COLORS.gray, transition: "all .2s", opacity: menuOpen ? 0 : 1 }} />
              <span style={{ display: "block", width: 24, height: 2, background: menuOpen ? COLORS.lime : COLORS.gray, transition: "all .2s", transform: menuOpen ? "rotate(-45deg) translate(5px, -5px)" : "none" }} />
            </button>
          </div>
        ) : (
          /* Desktop: inline links */
          <div style={{ display: "flex", gap: "clamp(0.8rem, 2.5vw, 1.8rem)", alignItems: "center" }}>
            {links.map((l) => (
              <button key={l} onClick={() => navTo(l)} style={{
                background: "none", border: "none", cursor: "pointer",
                fontFamily: "'DM Sans', sans-serif",
                fontSize: "clamp(12px, 2.5vw, 14px)", fontWeight: 600,
                letterSpacing: "0.08em", textTransform: "uppercase",
                color: page === l ? COLORS.lime : COLORS.gray,
                borderBottom: page === l ? `2px solid ${COLORS.lime}` : "2px solid transparent",
                paddingBottom: 2, transition: "all .2s",
              }}>{l}</button>
            ))}
          </div>
        )}
      </div>

      {/* Mobile dropdown */}
      {isMobile && menuOpen && (
        <div style={{
          background: "rgba(15,26,10,0.99)",
          borderTop: `1px solid ${COLORS.lime}33`,
          padding: "0.5rem 0",
        }}>
          {links.map((l) => (
            <button key={l} onClick={() => navTo(l)} style={{
              display: "block", width: "100%",
              background: "none", border: "none", cursor: "pointer",
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 15, fontWeight: 600,
              letterSpacing: "0.08em", textTransform: "uppercase",
              color: page === l ? COLORS.lime : COLORS.gray,
              textAlign: "left", padding: "0.75rem 1.5rem",
              borderLeft: page === l ? `3px solid ${COLORS.lime}` : "3px solid transparent",
            }}>{l}</button>
          ))}
        </div>
      )}
    </nav>
  );
}

