// ── GIFT CARD MODAL ───────────────────────────────────────────────────────────
function GiftCardModal({ option, onClose, onSuccess }) {
  const [step, setStep] = useState<"info"|"payment"|"done">("info");
  const [form, setForm] = useState({ purchaserName: "", purchaserEmail: "", recipientName: "", recipientEmail: "", isGift: false });
  const [error, setError] = useState("");
  const [processing, setProcessing] = useState(false);
  const stripeRef = useRef<any>(null);
  const cardRef = useRef<any>(null);

  useEffect(() => {
    if (step === "payment") {
      loadStripe().then((stripe: any) => {
        stripeRef.current = stripe;
        const elements = stripe.elements();
        const card = elements.create("card", {
          hidePostalCode: true,
          style: {
            base: { color: "#ffffff", fontFamily: "'DM Sans', sans-serif", fontSize: "18px", backgroundColor: "transparent", "::placeholder": { color: "#6b7280" }, iconColor: "#C8F542" },
            invalid: { color: "#ef4444", iconColor: "#ef4444" },
          },
        });
        setTimeout(() => {
          const el = document.getElementById("gc-stripe-element");
          if (el && el.childElementCount === 0) { card.mount("#gc-stripe-element"); cardRef.current = card; }
        }, 100);
      });
    }
  }, [step]);

  const goToPayment = () => {
    if (!form.purchaserName.trim() || !form.purchaserEmail.trim()) { setError("Name and email are required."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.purchaserEmail)) { setError("Please enter a valid email."); return; }
    if (form.isGift && form.recipientEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.recipientEmail)) { setError("Please enter a valid recipient email."); return; }
    setError(""); setStep("payment");
  };

  const handlePurchase = async () => {
    if (!stripeRef.current || !cardRef.current) { setError("Payment form not ready. Please wait."); return; }
    setProcessing(true); setError("");
    try {
      const intentRes = await fetch("/api/create-gift-card-payment", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ lessons: option.lessons, purchaserName: form.purchaserName, purchaserEmail: form.purchaserEmail }),
      });
      const { clientSecret, error: intentErr } = await intentRes.json();
      if (intentErr) throw new Error(intentErr);
      const { error: stripeErr } = await stripeRef.current.confirmCardPayment(clientSecret, { payment_method: { card: cardRef.current } });
      if (stripeErr) throw new Error(stripeErr.message);
      await fetch("/api/send-gift-card", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          purchaserName: form.purchaserName, purchaserEmail: form.purchaserEmail,
          recipientName: form.isGift ? form.recipientName : form.purchaserName,
          recipientEmail: form.isGift ? form.recipientEmail : form.purchaserEmail,
          lessons: option.lessons,
        }),
      });
      setStep("done");
    } catch (err: any) { setError(err.message || "Purchase failed. Please try again."); }
    setProcessing(false);
  };

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 1000, background: "rgba(0,0,0,0.75)", display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={onClose}>
      <div style={{ background: COLORS.dark, borderRadius: 16, padding: "2rem", maxWidth: 420, width: "100%", border: `1px solid ${COLORS.lime}`, boxShadow: "0 24px 80px rgba(0,0,0,0.8)" }} onClick={e => e.stopPropagation()}>
        {step === "done" ? (
          <>
            <div style={{ textAlign: "center", padding: "1rem 0" }}>
              <div style={{ fontSize: 52, marginBottom: 12 }}>🎁</div>
              <h2 style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 28, color: COLORS.lime, letterSpacing: 2, margin: "0 0 8px" }}>Gift Card Sent!</h2>
              <p style={{ fontFamily: "'DM Sans', sans-serif", color: COLORS.gray, fontSize: 14, lineHeight: 1.7, margin: "0 0 20px" }}>
                {form.isGift && form.recipientEmail ? `Your gift card has been emailed to ${form.recipientEmail}.` : `Your gift card has been emailed to ${form.purchaserEmail}.`}
                {option.lessons === 6 ? " Plus a bonus free lesson card!" : ""}
              </p>
              <button onClick={onClose} style={{ background: COLORS.lime, color: COLORS.dark, border: "none", borderRadius: 10, padding: "0.85rem 2rem", fontFamily: "'Bebas Neue', sans-serif", fontSize: 18, letterSpacing: 2, cursor: "pointer" }}>DONE</button>
            </div>
          </>
        ) : step === "info" ? (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
              <div>
                <h3 style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 22, color: COLORS.lime, letterSpacing: 2, margin: 0 }}>Buy Gift Card</h3>
                <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: COLORS.gray, margin: "4px 0 0" }}>{option.label} · ${option.price}.00</p>
              </div>
              <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.gray, fontSize: 20, cursor: "pointer" }}>✕</button>
            </div>
            {[
              ["Your Name", "purchaserName", "text", "John Smith"],
              ["Your Email", "purchaserEmail", "email", "you@email.com"],
            ].map(([label, key, type, ph]) => (
              <div key={key} style={{ marginBottom: 14 }}>
                <label style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 11, color: COLORS.gray, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", display: "block", marginBottom: 6 }}>{label}</label>
                <input type={type} placeholder={ph} aria-label={ph} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))}
                  style={{ width: "100%", boxSizing: "border-box", background: COLORS.forest, border: `1px solid ${COLORS.mid}`, borderRadius: 8, padding: "0.75rem 1rem", color: COLORS.white, fontFamily: "'DM Sans', sans-serif", fontSize: 14, outline: "none" }} />
              </div>
            ))}
            <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer", marginBottom: 14 }}>
              <input type="checkbox" checked={form.isGift} onChange={e => setForm(f => ({ ...f, isGift: e.target.checked }))} />
              <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, color: COLORS.white }}>This is a gift for someone else</span>
            </label>
            {form.isGift && (
              <>
                {[["Recipient Name", "recipientName", "text", "Jane Smith"], ["Recipient Email", "recipientEmail", "email", "them@email.com"]].map(([label, key, type, ph]) => (
                  <div key={key} style={{ marginBottom: 14 }}>
                    <label style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 11, color: COLORS.gray, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", display: "block", marginBottom: 6 }}>{label}</label>
                    <input type={type} placeholder={ph} aria-label={ph} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))}
                      style={{ width: "100%", boxSizing: "border-box", background: COLORS.forest, border: `1px solid ${COLORS.mid}`, borderRadius: 8, padding: "0.75rem 1rem", color: COLORS.white, fontFamily: "'DM Sans', sans-serif", fontSize: 14, outline: "none" }} />
                  </div>
                ))}
              </>
            )}
            {error && <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: "#ef4444", margin: "0 0 12px" }}>{error}</p>}
            <button onClick={goToPayment} style={{ width: "100%", background: COLORS.lime, color: COLORS.dark, border: "none", borderRadius: 10, padding: "0.9rem", fontFamily: "'Bebas Neue', sans-serif", fontSize: 20, letterSpacing: 2, cursor: "pointer", boxShadow: "0 4px 16px rgba(200,245,66,0.25)" }}>
              CONTINUE TO PAYMENT →
            </button>
          </>
        ) : (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
              <div>
                <h3 style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 22, color: COLORS.lime, letterSpacing: 2, margin: 0 }}>Payment</h3>
                <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: COLORS.gray, margin: "4px 0 0" }}>{option.label} · ${option.price}.00</p>
              </div>
              <button onClick={() => setStep("info")} style={{ background: "none", border: "none", color: COLORS.gray, fontSize: 13, cursor: "pointer", fontFamily: "'DM Sans', sans-serif" }}>← Back</button>
            </div>
            <div style={{ display: "flex", gap: 4, marginBottom: 16 }}>
              {[["#1A1F71","VISA"],["mc","MC"],["#006FCF","AMEX"]].map(([bg, label]) => (
                <div key={label} style={{ background: bg === "mc" ? "#1a1a1a" : bg, borderRadius: 4, padding: "3px 7px", height: 22, display: "flex", alignItems: "center" }}>
                  {bg === "mc" ? <svg width="28" height="16" viewBox="0 0 28 16"><circle cx="10" cy="8" r="8" fill="#EB001B"/><circle cx="18" cy="8" r="8" fill="#F79E1B" opacity="0.9"/></svg>
                    : <span style={{ fontFamily: "Arial", fontWeight: 900, fontSize: 9, color: "#fff", letterSpacing: "0.04em" }}>{label}</span>}
                </div>
              ))}
              <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 5, background: "rgba(99,91,255,0.14)", border: "1px solid rgba(99,91,255,0.3)", borderRadius: 6, padding: "3px 8px" }}>
                <svg width="8" height="8" viewBox="0 0 8 8"><circle cx="4" cy="4" r="4" fill="#635BFF"/></svg>
                <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 9, color: "#a29dff", fontWeight: 700 }}>Stripe</span>
              </div>
            </div>
            <div id="gc-stripe-element" style={{ background: "#080f07", border: "1.5px solid rgba(200,245,66,0.28)", borderRadius: 10, padding: "1rem", marginBottom: 14, boxShadow: "inset 0 2px 10px rgba(0,0,0,0.4)" }} />
            {error && <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: "#ef4444", margin: "0 0 12px" }}>{error}</p>}
            <button onClick={handlePurchase} disabled={processing} style={{ width: "100%", background: processing ? COLORS.mid : COLORS.lime, color: COLORS.dark, border: "none", borderRadius: 10, padding: "0.9rem", fontFamily: "'Bebas Neue', sans-serif", fontSize: 20, letterSpacing: 2, cursor: processing ? "not-allowed" : "pointer", boxShadow: processing ? "none" : "0 4px 16px rgba(200,245,66,0.25)" }}>
              {processing ? "PROCESSING..." : `PAY $${option.price} →`}
            </button>
            <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 10, color: COLORS.gray, textAlign: "center", marginTop: 12, marginBottom: 0 }}>🔒 256-bit TLS · PCI DSS Compliant · Powered by Stripe</p>
          </>
        )}
      </div>
    </div>
  );
}

